import {restoreBook, pageHtml, documentHtml, bookCss} from './book-template.mjs';

export function setupStorybook({getStory, updateDraft, saveBook, notify}) {
  const dialog=document.createElement('dialog');
  dialog.id='bookDialog';dialog.className='book-dialog';dialog.setAttribute('aria-labelledby','bookDialogTitle');
  dialog.innerHTML=`<div class="book-editor-header"><div><h2 id="bookDialogTitle">Make it a storybook.</h2><p>Arrange their own words into pages. Nothing is rewritten.</p></div><button class="close" id="closeBook" aria-label="Back to story editor">×</button></div><div class="book-workspace"><div class="book-options"><label>Book title<input id="bookTitle" maxlength="120"></label><label>Storyteller<input id="bookPerson" maxlength="80"></label><label>Question that started this story<textarea id="bookQuestion" rows="3" maxlength="600" placeholder="e.g. What did home look like when you were little?"></textarea></label><p class="small">Shown before the original story and any translation. Keep the question in its original language, or add it if this memory was recorded without a prompt.</p><label>A note for your family<textarea id="bookDedication" rows="3" maxlength="400" placeholder="For our children, and the stories they will carry."></textarea></label><label>Cover photo (optional)<input id="bookPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="removeBookPhoto" class="text-button" hidden>Remove cover photo</button><p class="small">Use a family photo, or keep the cover in warm colors. Photos stay in this browser.</p><hr><label id="bookPageLabel">Words on this page<textarea id="bookPageText" rows="8"></textarea></label><p id="bookPageHint" class="small"></p><div id="bookPageImageOptions"><label>Picture for this page<input id="bookPagePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Picture caption<input id="bookPageCaption" maxlength="160" placeholder="Who or what is in this picture?"></label><button id="removePagePhoto" class="text-button" hidden>Remove page picture</button><p class="small">Choose a family photo or an illustration you have. Automatic AI illustrations are not connected yet.</p></div><div class="button-row"><button id="addBookPage" class="text-button">Add a page</button><button id="removeBookPage" class="danger-link">Remove this page</button></div></div><div class="book-preview"><div class="book-navigation"><button id="bookPrevious" class="button secondary" aria-label="Previous book page">Previous</button><span id="bookPosition" role="status" aria-live="polite"></span><button id="bookNext" class="button secondary" aria-label="Next book page">Next</button></div><div id="bookCanvas"></div></div></div><p class="small">Downloaded books and PDFs are not password-protected. Anyone with the file can read it and play any included recording. Share only with people you trust.</p><p id="bookStatus" class="status" role="status"></p><div class="book-editor-footer"><div><button id="saveBook" class="button primary">Save storybook</button><p class="small">Keep it in this browser. Downloading is optional.</p></div><div class="book-download-options" aria-label="Choose a download format"><div class="book-download-option"><button id="downloadBook" class="button secondary" aria-describedby="digitalBookHelp">Download digital book</button><p id="digitalBookHelp"></p><p class="small">Open in a browser to read and listen, even offline.</p></div><div class="book-download-option"><button id="printBookPdf" class="button secondary" aria-describedby="pdfBookHelp">Print / Save PDF</button><p id="pdfBookHelp"><strong>Text and photos only. No voice recording.</strong></p><p class="small">Want to keep their voice too? Download the digital book as well.</p></div></div></div>`;
  document.body.append(dialog);
  const style=document.createElement('style');style.textContent=bookCss;document.head.append(style);
  const $=id=>dialog.querySelector('#'+id);
  let book,story,index=0,saving=false,photoLoading=false;
  function message(text,error=false){$('bookStatus').textContent=text;$('bookStatus').className='status'+(error?' error':'')}
  function draft(){updateDraft(structuredClone(book))}
  function redraw(){
    $('bookCanvas').innerHTML=pageHtml(book,index);
    $('bookPosition').textContent=index===0?`Cover / ${book.pages.length} pages`:`Page ${index} of ${book.pages.length}`;
    $('bookPrevious').disabled=index===0;$('bookNext').disabled=index>=book.pages.length;
    $('bookPageLabel').hidden=index===0;
    $('bookPageText').value=index?book.pages[index-1].text:'';$('bookPageImageOptions').hidden=index===0;$('bookPageCaption').value=index?(book.pages[index-1].caption||''):'';$('removePagePhoto').hidden=!index||!book.pages[index-1].photo;
    $('bookPageText').lang=index?book.pages[index-1].language:'en';
    $('removeBookPage').hidden=index===0||book.pages.length<=1;
    $('addBookPage').disabled=book.pages.length>=50;
    $('bookPageHint').textContent=index?(book.pages[index-1].translation?'This is a translation page. Review it with your family.':'Edits here change the book, not the original transcript.'):'Turn to a page to edit its words.';
    $('removeBookPhoto').hidden=!book.photo;
  }
  function valid(requirePicture=false){if(photoLoading){message('Please wait for the cover photo to finish loading.',true);return false}if(requirePicture&&!book.photo&&!book.pages.some(p=>p.photo)){message('Add a cover picture or a picture to a story page before exporting your picture book.',true);return false}if(!book.title.trim()){message('Add a book title first.',true);$('bookTitle').focus();return false}if(book.pages.every(p=>!p.text.trim())){message('Add words to at least one page.',true);return false}return true}
  function close(){if(saving||photoLoading)return;draft();dialog.close()}
  $('closeBook').onclick=close;
  dialog.addEventListener('cancel',e=>{if(saving||photoLoading)e.preventDefault();else draft()});
  for(const [id,key]of [['bookTitle','title'],['bookPerson','person'],['bookDedication','dedication'],['bookQuestion','question']])$(id).oninput=e=>{book[key]=e.target.value;$('bookCanvas').innerHTML=pageHtml(book,index);draft()};
  $('bookPageText').oninput=e=>{if(index){book.pages[index-1].text=e.target.value;$('bookCanvas').innerHTML=pageHtml(book,index);draft();message(e.target.value.length>900?'This page is long. Add another page and move some words to keep the print layout readable.':'')}};
  $('bookPrevious').onclick=()=>{index--;redraw()};$('bookNext').onclick=()=>{index++;redraw()};
  $('addBookPage').onclick=()=>{if(book.pages.length>=50)return;const at=index||0;const source=index?book.pages[index-1]:{language:story.language,translation:false};book.pages.splice(at,0,{text:'',photo:'',caption:'',language:source.language,translation:source.translation});index=at+1;draft();redraw();$('bookPageText').focus()};
  $('removeBookPage').onclick=()=>{if(!index||book.pages.length<=1)return;if(book.pages[index-1].text.trim()&&!confirm('Remove this page from the book? The original transcript stays unchanged.'))return;book.pages.splice(index-1,1);index=Math.min(index,book.pages.length);draft();redraw()};
  async function addPhoto(e,cover){
    const file=e.target.files[0];if(!file)return;
    if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){message('Choose a JPG, PNG, or WebP photo smaller than 8 MB.',true);e.target.value='';return}
    photoLoading=true;const pageIndex=index-1;for(const id of ['bookPrevious','bookNext','addBookPage','removeBookPage','saveBook','downloadBook','printBookPdf','bookPhoto','bookPagePhoto'])$(id).disabled=true;message('Preparing your picture…');
    const url=URL.createObjectURL(file);
    try{const image=new Image();image.src=url;await image.decode();const scale=Math.min(1,1400/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.85);if(cover)book.photo=data;else if(book.pages[pageIndex])book.pages[pageIndex].photo=data;draft();redraw();message('Picture added. Save the storybook to keep it on this device.')}catch{message('This photo could not be opened. Try a different JPG or PNG.',true)}finally{URL.revokeObjectURL(url);photoLoading=false;e.target.value='';for(const id of ['addBookPage','removeBookPage','saveBook','downloadBook','printBookPdf','bookPhoto','bookPagePhoto'])$(id).disabled=false;redraw()}
  };
  $('bookPhoto').onchange=e=>addPhoto(e,true);$('bookPagePhoto').onchange=e=>addPhoto(e,false);$('bookPageCaption').oninput=e=>{if(index){book.pages[index-1].caption=e.target.value;draft();$('bookCanvas').innerHTML=pageHtml(book,index)}};$('removePagePhoto').onclick=()=>{if(index){book.pages[index-1].photo='';draft();redraw()}};
  $('removeBookPhoto').onclick=()=>{book.photo='';draft();redraw()};
  $('saveBook').onclick=async()=>{if(!valid())return;saving=true;$('saveBook').disabled=true;message('Saving your storybook…');try{if(await saveBook(structuredClone(book))){dialog.close();notify('Storybook saved on this device. Download the digital book for backup.')}else message('The storybook could not be saved. Download the digital book to keep a copy.',true)}catch{message('The storybook could not be saved. Download a copy instead.',true)}finally{saving=false;$('saveBook').disabled=false}};
  function filename(){return (book.title||'family-storybook').replace(/[^\p{L}\p{N}-]+/gu,'-')+'-storybook.html'}
  async function audioData(){return story.audio?new Promise((ok,no)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=no;reader.readAsDataURL(story.audio)}):''}
  $('downloadBook').onclick=async()=>{if(!valid(true))return;$('downloadBook').disabled=true;try{const html=documentHtml(book,await audioData(),story.example);const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename();a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);message('Digital book downloaded. Its recording is included when you attached audio.')}catch{message('The download could not be created. Try Print / Save PDF for the text and pictures.',true)}finally{$('downloadBook').disabled=false}};
  $('printBookPdf').onclick=()=>{if(!valid(true))return;const win=window.open('','_blank');if(!win){message('Allow a new tab to open so you can print or save your book as a PDF.',true);return}win.opener=null;win.document.open();win.document.write(documentHtml(book,'',story.example));win.document.close();message('Your printable book opened in a new tab. Select Print / Save as PDF there. Audio is available in the digital book.')};
  function openBook(){story=getStory();if(!story?.text?.trim())return false;book=restoreBook(story);index=0;$('digitalBookHelp').textContent=story.audio?'Includes text, photos, and the original voice recording.':'Includes text and photos. This story has no voice recording attached.';$('bookTitle').value=book.title;$('bookPerson').value=book.person;$('bookDedication').value=book.dedication;$('bookQuestion').value=book.question;message('Preview and edit your pages. The original transcript is kept separately.');redraw();draft();dialog.showModal();return true};
  openBook.lock=()=>{book=null;story=null;index=0;dialog.close();$('bookCanvas').replaceChildren();for(const input of dialog.querySelectorAll('input,textarea'))input.value='';$('bookStatus').textContent='';};
  return openBook;
}
